(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,73047,e=>{"use strict";let a=[{slug:"heritage-bowl-youth-day-drop",title:"Heritage Bowl Launch Drops on Youth Day",date:"16 June 2026",category:"Collection Drops",urgency:"drop",section:"drops",excerpt:"A numbered South African heritage bowl lands for one day only, with loyalty early access before public release.",img:"/images/bowl-03-sa-heritage-series.png",alt:"Papa Pasta heritage bowl collection drop",ctaLabel:"Join Early Access",ctaHref:"/loyalty/",dropMeta:"500 units · Loyalty window opens first",content:"<p>The Heritage Bowl collection is built for customers who treat their pasta bowl like a badge. The drop opens on Youth Day with 500 numbered pieces and a loyalty early-access window before public release.</p><p>Members will see the collection preview first, then stores will open public claim windows while stock lasts.</p>"},{slug:"cbd-gardens-store-launch",title:"CBD Gardens Store Launch",date:"July 2026",category:"New Store Launches",urgency:"launch",section:"news",excerpt:"Papa Pasta expands the Cape Town network with a Gardens launch window, opening offer, and loyalty invite list.",img:"/images/franchisee-store-coral-teal.png",alt:"Papa Pasta Cape Town Gardens store launch",ctaLabel:"Find Locations",ctaHref:"/locations/",dropMeta:"Cape Town · Launch offer to be announced",content:"<p>The next Cape Town zone is loading. The Gardens launch will include a first-week opening offer, in-store loyalty signup, and a limited bowl allocation for launch-day visitors.</p><p>Follow the locations page for the confirmed opening day, delivery availability, and launch queue details.</p>"},{slug:"blackout-bomber-live",title:"Blackout Bomber Jacket Is Live",date:"June 2026",category:"Merch Drops",urgency:"drop",section:"drops",excerpt:"The first black-on-black Papa Pasta outerwear piece is live with reflective crest details and limited sizing.",img:"/images/digital-stories-reels.png",alt:"Papa Pasta blackout bomber merch drop",ctaLabel:"Shop Merch",ctaHref:"/merch/",dropMeta:"Live now · XS-XXL",content:"<p>The Blackout Bomber is the first Papa Pasta jacket built for the cyber crest era: satin shell, reflective mark, and black-on-black finish until the light hits.</p><p>Sizes are limited and will not be restocked in the same configuration.</p>"},{slug:"level-up-loyalty-loading",title:"Level Up Loyalty Is Loading",date:"June 2026",category:"Loyalty Updates",urgency:"drop",section:"news",badge:"Coming soon",excerpt:"Earn rewards on pasta, unlock merch early access, and get collection-drop previews before the public queue.",img:"/images/digital-mobile-app.png",alt:"Papa Pasta Level Up loyalty program preview",ctaLabel:"Join Loyalty",ctaHref:"/loyalty/",dropMeta:"Waitlist open · Early access rewards",content:"<p>Level Up connects the whole Papa Pasta universe: orders, merch drops, launch events, and limited collections.</p><p>The first member benefits include birthday pasta rewards, drop alerts, early access windows, and launch invites.</p>"},{slug:"pasta-shape-sauce",title:"Why Shape Matters: The Golden Blend of Pasta + Sauce",date:"May 2026",category:"Menu/Seasonal Drops",urgency:"story",section:"drops",excerpt:"Flat noodles hold cream. Tubes trap meat. The right shape makes or breaks a sauce.",img:"/images/menu-pasta-shape-pairing.png",alt:"Pasta shape and sauce pairing guide",ctaLabel:"View Menu",ctaHref:"/menu/",content:"<p>Every shape of pasta was engineered for a reason. Fettuccini's flat ribbons cradle Alfredo cream. Penne's tubes trap chunky ragù. Farfalle's pinched middle creates textural contrast. At Papa Pasta, we obsess over this marriage — because a perfect sauce on the wrong shape is a missed opportunity.</p><p>Our commissary produces six core shapes daily, each matched to its ideal sauce partner. We call it the Golden Blend: the moment when pasta and sauce become inseparable.</p>"},{slug:"inside-commissary",title:"Inside the Commissary: Where Obsession Lives",date:"April 2026",category:"Brand Stories",urgency:"story",section:"news",excerpt:"Behind-the-scenes at the central kitchen powering every bowl across the network.",img:"/images/central-kitchen-concept.png",alt:"Inside the Papa Pasta commissary",ctaLabel:"Read Our Story",ctaHref:"/story/",content:"<p>At 4:00 AM, while Cape Town sleeps, our commissary comes alive. Fresh eggs are cracked, flour is weighed, and dough is kneaded by hand — then rolled through Italian extruders that shape it into ribbons, tubes, and shells.</p><p>Nothing is frozen. Nothing is pre-made. Every batch is dated, tasted, and approved before it leaves for our stores. This is the engine behind every Papa Pasta bowl.</p>"},{slug:"art-of-crest",title:"The Art of the Crest: Colour Story Philosophy",date:"March 2026",category:"Brand Stories",urgency:"story",section:"news",excerpt:"How Papa Pasta gives every franchise a unique visual identity through colour story.",img:"/images/colour-story-colour-wheel.png",alt:"Colour story wheel",ctaLabel:"View Gallery",ctaHref:"/gallery/",content:"<p>The Living Crest system was born from a simple insight: no two neighbourhoods are the same, so no two stores should look the same. Every Papa Pasta franchise receives a unique colour identity — three colours chosen by the franchisee that become their store's visual signature.</p><p>From neon gamer drops inspired by Twitch culture, to heritage palettes rooted in South African history, the crest is more than a logo. It's the visual proof that this store belongs to this place.</p>"},{slug:"takeover-101",title:"TakeOver 101: Partnership Model",date:"Feb 2026",category:"Brand Stories",urgency:"story",section:"news",excerpt:"How brands like MTN, Vodacom and Nedbank light up a Papa Pasta for a day.",img:"/images/takeover-vodacom.png",alt:"Brand takeover partnership event",ctaLabel:"See Events",ctaHref:"/events/",content:"<p>A Papa Pasta TakeOver is when a brand partners with us to create a limited-edition menu, custom packaging, and an in-store experience for one day only. We've hosted TakeOvers with telecom brands, rugby teams, and local artists — each one completely unique.</p><p>The formula is simple: our kitchen, their vision. The result is always a sell-out.</p>"},{slug:"papa-pops-origin",title:"Papa Pops: The Snack That Surprised Everyone",date:"Jan 2026",category:"Menu/Seasonal Drops",urgency:"story",section:"drops",excerpt:"From test kitchen to fan favourite. The origin story of our crunchy pasta bites.",img:"/images/papa-pops-peri-peri.png",alt:"Papa Pops crunchy pasta bites",ctaLabel:"View Menu",ctaHref:"/menu/",content:"<p>It started as an experiment: what if we deep-fried offcuts of fresh pasta and tossed them in spice? The first batch — Cheesy Braai flavour — disappeared in minutes during a staff tasting. We knew we had something.</p><p>Today, Papa Pops are one of our best-selling items. Peri-Peri, Sweet Chutney, and the original Cheesy Braai. Three flavours. One obsession.</p>"},{slug:"franchise-forecast",title:"Franchise Forecast: Why Pasta Now",date:"Dec 2025",category:"Brand Stories",urgency:"story",section:"news",excerpt:"Market data, capital requirements and the first-mover gap in South African fast-casual.",img:"/images/franchise-store-concept.png",alt:"Papa Pasta franchise store concept",ctaLabel:"Visit Franchise Site",ctaHref:"https://franchise.papapasta.co.za/",content:"<p>South Africa has 2,500+ chicken outlets. It has hundreds of burger joints. But it has zero dedicated pasta QSR franchises. That gap is not a weakness — it is an opportunity.</p><p>Papa Pasta was built to fill it. With a central commissary, a compact 40m² store footprint, and a menu that travels across all nine provinces, we are designing a brand that scales without losing soul.</p>"}];e.s(["blogPosts",0,a,"dropsCategories",0,["All","Merch Drops","Collection Drops","Menu/Seasonal Drops"],"getDropsPosts",0,function(){return a.filter(e=>"drops"===e.section)},"getNewsPosts",0,function(){return a.filter(e=>"news"===e.section)},"getPostBySlug",0,function(e){return a.find(a=>a.slug===e)},"newsCategories",0,["All","New Store Launches","Loyalty Updates","Brand Stories"]])},95953,e=>{"use strict";var a=e.i(43476),t=e.i(71645),s=e.i(18566),o=e.i(22016),r=e.i(73047);e.s(["default",0,function({slug:e}){let i=(0,s.useRouter)(),n=e?(0,r.getPostBySlug)(e):void 0,l=n?`/${n.section}/${n.slug}/`:"/drops/";return(0,t.useEffect)(()=>{i.replace(l)},[i,l]),(0,a.jsx)("div",{className:"min-h-[50vh] flex items-center justify-center bg-black text-white px-4",children:(0,a.jsxs)("p",{className:"text-white/75 text-center",children:["This page has moved."," ",(0,a.jsx)(o.default,{href:l,className:"text-lime-300 hover:text-white underline",children:"Continue"}),"."]})})}])},24414,e=>{"use strict";var a=e.i(43476),t=e.i(95953);e.s(["default",0,function(){return(0,a.jsx)(t.default,{})}])}]);